CREATE OR REPLACE FUNCTION public.sanitize_unverified_law_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  source_names text[] := '{}'::text[];
  law_names text[] := '{}'::text[];
begin
  -- Only police student-facing ready enrichment. Pending/review rows may retain
  -- draft/debug metadata for diagnosis.
  if lower(coalesce(new.analysis_status, '')) <> 'ready' then
    return new;
  end if;

  if nullif(btrim(coalesce(new.law, '')), '') is null then
    return new;
  end if;

  -- Evidence-backed legal review owns these states. This guard must not erase a
  -- reviewed extension merely because the official stem did not spell it out.
  if lower(coalesce(new.legal_status, '')) in ('verified_current', 'changed') then
    return new;
  end if;

  -- Official-source support is intentionally limited to the immutable question
  -- and option text. AI explanation fields are never accepted as self-evidence.
  source_names := public.extract_legal_canonical_names(
    concat_ws(
      ' ',
      new.question,
      new.opt_a,
      new.opt_b,
      new.opt_c,
      new.opt_d
    )
  );
  law_names := public.extract_legal_canonical_names(new.law);

  -- Fail closed without creating manual-work debt: law is optional enrichment.
  -- If it is not canonical, or any claimed canonical law is absent from the
  -- official question/options, drop the law field and keep the explanation.
  if coalesce(cardinality(law_names), 0) = 0
     or not (law_names <@ source_names) then
    new.law := null;

    -- Keep the reference index consistent even when this trigger was activated
    -- by analysis_status rather than an UPDATE OF law statement.
    new.legal_canonical_names := source_names;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_question_legal_canonical_names()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.legal_canonical_names := public.extract_legal_canonical_names(
    concat_ws(' ', new.question, new.opt_a, new.opt_b, new.opt_c, new.opt_d, new.law)
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.auto_enable_ai_for_pending_question()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  enabled_now boolean;
begin
  if new.source_exam_code is not null and new.analysis_status = 'pending' then
    select enabled into enabled_now from public.ai_analysis_job_config where id = true;
    if coalesce(enabled_now,false) = false then
      perform public.enable_swsi_ai_analysis();
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.auto_stop_ai_when_queue_drains()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  enabled_now boolean;
begin
  if old.analysis_status is distinct from new.analysis_status
     and new.analysis_status in ('ready','review') then
    select enabled into enabled_now from public.ai_analysis_job_config where id = true;
    if coalesce(enabled_now,false) = true then
      perform public.maybe_stop_swsi_ai_analysis();
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_analysis_completed_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.analysis_status = 'ready' and old.analysis_status is distinct from 'ready' then
    new.analysis_completed_at := now();
  elsif new.analysis_status is distinct from 'ready' and old.analysis_status = 'ready' then
    new.analysis_completed_at := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_ai_answer_meta_commentary()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  s text;
begin
  if new.analysis_status = 'ready' then
    s := concat_ws(' ', new.exp_why, new.exp_others, new.exp_trap, new.mnemonic, new.extension, new.law);
    if s ~* '(題庫答案|題庫正解|答案待查|答案有瑕疵|官方答案|本題官方|官方正確|官方全體給分|建議.{0,12}(查|複查).{0,12}答案|已核對答案|選項判定有爭議)' then
      raise exception 'AI analysis contains forbidden answer-meta commentary' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reset_ai_analysis_on_official_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.source_exam_code is not null and (
       new.question is distinct from old.question
    or new.opt_a is distinct from old.opt_a
    or new.opt_b is distinct from old.opt_b
    or new.opt_c is distinct from old.opt_c
    or new.opt_d is distinct from old.opt_d
    or new.answer is distinct from old.answer
    or new.accepted_answers is distinct from old.accepted_answers
    or new.grading_mode is distinct from old.grading_mode
  ) then
    new.major := null;
    new.topic := null;
    new.keywords := null;
    new.exp_why := null;
    new.exp_others := null;
    new.exp_trap := null;
    new.exp_raw := null;
    new.mnemonic := null;
    new.extension := null;
    new.law := null;
    new.mistake := null;
    new.analysis_status := 'pending';
    new.analysis_attempts := 0;
    new.analysis_error := null;
    new.analysis_started_at := null;
    new.analysis_completed_at := null;
    new.analysis_last_attempt_at := null;
  end if;
  return new;
end;
$function$
